head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF05950";
scwin.curTp = 1;            // 현재 탭 번호 1~7 (원본 전역 ELW_MBR_INFO_TP_CD = 탭 번호, §7.1)
scwin.trJob = "";           // 처리구분 I: 신규, U: 수정 (확인 문구·심사서류첨부 검증에만 쓴다 — 삭제는 이 값을 바꾸지 않는다, §8 #3)
// 원본 : /lstproc/ULDSTF05950.gfm (회원사알림관리 — 메뉴 화면 950×747)
/*
 * 화면 동작
 *  - 탭 7개. 탭 번호가 원본 ELW_MBR_INFO_TP_CD 이고 모든 분기의 기준이다.
 *      1 상장제한종목 · 2 지수구성종목변동        — 목록 + 입력(신규·저장·삭제), 저장 modify-uly-chg / 삭제 remove-uly-chg
 *      3 발행가능 코스닥150 기초자산              — 조회 전용 (기준년월)
 *      4 심사서류첨부(구분 3) · 5 기타안내(구분 4) — 목록 + 입력(신규·저장·삭제), 저장 modify-decl-contn / 삭제 remove-decl-contn
 *      6 발행가능 KOSPI 200 기초자산             — 조회 전용 (분기 콤보), 엑셀
 *      7 발행가능행사가격                        — 조회 전용 (기준년월·권리형태), 엑셀
 *  - 조회하면 입력란을 비우고 잠근 뒤, 상장제한종목·지수구성종목변동은 첫 행을 입력란에 보여 준다(수정 상태).
 *  - 명세에 등록(register) API 가 없어 신규·수정 모두 modify-* 를 부른다(§5 차이 #1, §10 #1).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05950/ULDSTF05950.md (§번호는 이 문서의 절)
 */

// 고정값
scwin.LIST_TP_CD = { 1 : "1", 2 : "2" };        // 상장제한종목·지수구성종목변동 → elwMbrInfoTpCd (원본 탭 번호 그대로)
scwin.DECL_TP_CD = { 4 : "3", 5 : "4" };        // 심사서류첨부·기타안내 → elwMbrInfoTpCd (원본 fn_trs 의 "3"·"4", 목록 조회도 같은 값)

// 탭별 상단 안내문 (원본 fn_SetTitle). 6·7 은 안내문을 숨긴다.
scwin.TITLE = {
    1 : "* 발행사가 코드 발급한 ELW의 기초자산이 제한사유 해당종목이고 만기가 제한사유 발생시점 이후에 도래하는 경우\n  상장공시제출시스템의 상장신청 탭을 선택하였을때 안내 메시지를 표시합니다.",
    2 : "* 발행사가 조회화면에 저장되어 있는 종목을 코드발급한 경우, 상장공시제출시스템의 상장신청 탭을 선택하였을때 안내 메시지를 표시합니다.",
    3 : "",
    4 : "* 지정한 표시기간 동안 발행사 담당자가 상장공시제출시스템의 공시제출 탭을 선택했을 때 팝업화면으로 내용에 입력한 사항을 표시합니다.",
    5 : "* 메시지 표시기간은 입력값이 없으면 매월 말일 포함 직전 3영업일입니다."
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05950.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — 조회조건 기본값 → 조회 영역 Enter 키 바인딩 → 상장제한종목 탭 안내문·조건 → 분기 콤보 조회 → 상장제한종목 조회. 탭 본문 안 달력 바인딩은 탭 로드 때 scwin.MaxTab_01_ontabload 가 한다(규칙 45). (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 조회조건 기본값 — 현재 유효한 항목만 보기 체크(원본 checked), 기준년월 당월(원본 fn_setYYYYMM), 권리형태 콜(원본 codevalue C)
    dma_search.set("chkYn", "Y");
    dma_search.set("basYymm", $c.date.getServerDateTime("yyyyMM"));
    dma_search.set("rghtTpCd", "C");

    // 2) init 바인딩(1회) — 탭 밖 조회 영역 Enter 키(규칙 22). 탭 안 달력은 scwin.MaxTab_01_ontabload(규칙 37·45)
    $c.win.setEnterKeyEvent(tbl_search, scwin.btn_Search_onclick);

    // 3) 첫 탭(상장제한종목) 안내문·조회조건 표시 — 원본 ELW_MBR_INFO_TP_CD = 1, fn_SetTitle, showObj(…, false)
    scwin.curTp = 1;
    scwin.setTitle();
    scwin.setSearchCond();

    // 4) 분기 콤보(KOSPI 200 탭) — 원본 fn_Bas_YYMM_sync(비동기). 목록 조회와 무관해 순서만 지킨다.
    await scwin.selectBasYymm();

    // 5) 상장제한종목 조회 — 원본 fn_list_sync
    await scwin.searchList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.MaxTab_01_onchange
 * @author Inswave
 * @date 2026. 10. 28
 * @description 탭 변경. 탭에 맞는 조회조건을 보이고(분기는 둘째 항목, 기준년월은 당월로 되돌림) 안내문을 바꾼 뒤 다시 조회한다. (원본 MaxTab_01 OnSelChanged — §4, §6.2)
 * @param {String} tabId 탭 id
 * @param {Number} index 탭 순번
 * @returns
 * @hidden N
 */
scwin.MaxTab_01_onchange = async function (tabId, index) {
    try {
        scwin.curTp = Number(MaxTab_01.getSelectedTabIndex()) + 1;

        if (scwin.curTp === 6) {
            // 원본 cmb_Bas_YYMM.Index = 1 — 둘째 항목(0부터). 항목이 하나뿐이면 원본처럼 빈 값 (§8 #6, §10 #9)
            dma_search.set("basQtr", (dlt_listbasyymmdd.getRowCount() > 1) ? dlt_listbasyymmdd.getCellData(1, "value") : "");
        } else if (scwin.curTp === 3 || scwin.curTp === 7) {
            dma_search.set("basYymm", $c.date.getServerDateTime("yyyyMM"));    // 원본 fn_setYYYYMM
        }
        scwin.setSearchCond();
        scwin.setTitle();
        await scwin.searchList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05950.MaxTab_01_onchange" });
    }
};

/**
 * @method
 * @name scwin.MaxTab_01_ontabload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 탭 로드(탭마다 처음 그려질 때 한 번) — 로드된 탭 본문의 달력만 바인딩한다. 단일 달력은 checkCalendarFormat, 기간 쌍은 compareFromToDate 만(규칙 37·45). 첫 탭은 scwin.init 보다 먼저 온다. (§3)
 * @param {String} tabId 엔진 탭 id ("MaxTab_01_tab_{tabs id}")
 * @param {Number} index 로드된 탭 index
 * @param {String} userTabId w2:tabs id
 * @returns
 * @hidden N
 */
scwin.MaxTab_01_ontabload = async function (tabId, index, userTabId) {
    try {
        if (index === 0) {
            // [상장제한종목] 제한사유 발생시점·종료시점 — 서로 다른 칸이라 기간 관용구가 아니다
            $c.date.checkCalendarFormat(edt_SDate_1, "yyyyMMdd");
            $c.date.checkCalendarFormat(edt_EDate_1, "yyyyMMdd");
        } else if (index === 1) {
            // [지수구성종목변동] 지수편출일
            $c.date.checkCalendarFormat(edt_SDate_2, "yyyyMMdd");
        } else if (index === 3) {
            // [심사서류첨부] 메시지 표시기간
            $c.date.compareFromToDate(edt_SDate_4_1, edt_SDate_4_2, ["메시지 표시기간 시작일자", "메시지 표시기간 종료일자"]);
        } else if (index === 4) {
            // [기타안내] 메시지 표시기간
            $c.date.compareFromToDate(edt_SDate_5_1, edt_SDate_5_2, ["메시지 표시기간 시작일자", "메시지 표시기간 종료일자"]);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05950.MaxTab_01_ontabload" });
    }
};

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 조회 버튼 클릭 (조회 영역 Enter 키도 이 핸들러). 행사가격 탭이면 권리형태·기준년월을 검사한다. (원본 btn_Search onclick — §6.3)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        if (!await scwin.checkSearch()) return;
        await scwin.searchList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05950.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.cmb_Bas_YYMM_onviewchange
