 * @date 2026. 10. 28
 * @description 분기 콤보를 사용자가 바꾸면 다시 조회한다. 탭 변경에서 코드로 값을 넣을 때는 발생하지 않는다(중복 조회 방지). (원본 cmb_Bas_YYMM OnSelChange — §4)
 * @param {Object} info 변경 정보
 * @returns
 * @hidden N
 */
scwin.cmb_Bas_YYMM_onviewchange = async function (info) {
    try {
        await scwin.searchList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05950.cmb_Bas_YYMM_onviewchange" });
    }
};

