/**
 * @method
 * @name scwin.saveUlyChg
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상장제한종목(구분 1)·지수구성종목변동(구분 2) 저장. 입력란 값을 dma_ulychg 에 옮겨 ref 로 보낸다 — 신규·수정 같은 API. (원본 fn_trs 탭1·2 — saveElwUlyChgInfo, §5.8)
 * @param {Number} tp 탭 번호 (1·2)
 * @returns {Promise<Boolean>} 처리 성공 여부
 * @hidden N
 */
scwin.saveUlyChg = async function (tp) {
    const sbmOptions = {
        id : "sbm_saveUlyChg",
        method : "post",
        action : "/api/listing/lstproc/elw/mbr-noti/modify-uly-chg",
        ref : "dma_ulychg",
        target : "dma_result=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const form = (tp === 1) ? dma_form1 : dma_form2;
    // TODO: 명세에 처리구분(I/U)·사번 키가 없다 — 신규·수정 구분과 사번은 서버가 정하는지 확인 (§10 #1, #3)
    dma_ulychg.setEmptyValue();
    dma_ulychg.setJSON({
        elwMbrInfoTpCd : scwin.LIST_TP_CD[tp],
        isurCd : form.get("isurCd"),
        strtDd : form.get("strtDd"),
        endDd : (tp === 1) ? dma_form1.get("endDd") : "",    // 종료일자는 상장제한종목만(명세 주석)
        notiTitle : form.get("notiTitle"),
        notiContn : form.get("notiContn")
    });

    dma_result.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return false;    // 진행 중 처리가 있어 이번 호출은 건너뜀
    return await scwin.checkResult(result, (scwin.trJob === "I") ? "저장" : "수정");
};

