///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.searchList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 현재 탭 목록 조회. 입력란을 비우고 잠근 뒤 탭별 API 를 부르고, 상장제한종목·지수구성종목변동은 첫 행을 입력란에 보여 준다.
 * (원본 fn_list_sync — fn_Disable_Item + DataID/Reset, dts_List_1·2 OnLoadCompleted 의 fn_SetValue(RowPosition) — §6.1)
 * @returns
 * @hidden N
 */
scwin.searchList = async function () {
    const tp = scwin.curTp;

    // 원본 fn_Disable_Item — 입력란 비우고 잠금. 처리구분도 비운다(원본은 앞 탭 값을 이어 씀 — §8 #4)
    scwin.trJob = "";
    scwin.clearForm();
    scwin.setFormMode("disabled");

    let loaded = false;
    if (tp === 1) {
        loaded = await scwin.selectIsuLmt();
        if (loaded && dlt_isulimit.getRowCount() > 0) scwin.setValue(0);
    } else if (tp === 2) {
        loaded = await scwin.selectUlyChg();
        if (loaded && dlt_uly.getRowCount() > 0) scwin.setValue(0);
    } else if (tp === 3) {
        await scwin.selectStridxTop5();
    } else if (tp === 4 || tp === 5) {
        await scwin.selectDeclContn(tp);
    } else if (tp === 6) {
        await scwin.selectUlyNm();
    } else if (tp === 7) {
        await scwin.selectExerPrc();
    }
};

/**
 * @method
 * @name scwin.setTitle
 * @author Inswave
 * @date 2026. 10. 28
 * @description 탭별 상단 안내문과 [현재 유효한 항목만 보기] 표시. 6·7 탭은 안내문을 숨기고, 체크박스는 상장제한종목 탭에만 보인다. (원본 fn_SetTitle — §6.2)
 * @returns
 * @hidden N
 */
scwin.setTitle = function () {
    const tp = scwin.curTp;

    if (tp === 6 || tp === 7) {
        txa_Title.hide();
    } else {
        txa_Title.show("");
        txa_Title.setValue(scwin.TITLE[tp] ?? "");
    }

    if (tp === 1) {
        chk_DelYn.show("");
    } else {
        chk_DelYn.hide();
    }
};

/**
 * @method
 * @name scwin.setSearchCond
 * @author Inswave
 * @date 2026. 10. 28
 * @description 탭별 조회조건 표시 — 3 기준년월, 6 분기 콤보, 7 권리형태 + 기준년월, 그 밖은 모두 숨김. (원본 OnSelChanged·onload 의 showObj — §6.2)
 * @returns
 * @hidden N
 */
scwin.setSearchCond = function () {
    const tp = scwin.curTp;
    const visible = {
        txb_basYm : (tp === 3 || tp === 6 || tp === 7),
        cmb_Bas_YYMM : (tp === 6),
        txb_YYYYMM : (tp === 3 || tp === 7),
        label_26 : (tp === 7),
        rdo_RGHT_TP_CD : (tp === 7)
    };

    txb_basYm.setValue((tp === 6) ? "분기" : "기준년월");

    [txb_basYm, cmb_Bas_YYMM, txb_YYYYMM, label_26, rdo_RGHT_TP_CD].forEach(comp => {
        if (visible[comp.getID()]) {
            comp.show("");
        } else {
            comp.hide();
        }
    });
};

/**
 * @method
 * @name scwin.checkSearch
 * @author Inswave
 * @date 2026. 10. 28
 * @description 조회 조건 검사 — 발행가능행사가격 탭만 권리형태·기준년월(YYYYMM, 첫 자리 1 이상, 월 1~12)을 본다. (원본 btn_Search onclick — §6.3)
 * @returns {Promise<Boolean>} 통과하면 true
 * @hidden N
 */
scwin.checkSearch = async function () {
    if (scwin.curTp !== 7) return true;

    if ($c.util.isEmpty(dma_search.get("rghtTpCd"))) {
        await $c.win.alert("권리형태를 지정해주세요.");
        rdo_RGHT_TP_CD.focus();
        return false;
    }

    const basYymm = String(dma_search.get("basYymm") ?? "");
    if (basYymm === "") {
        await $c.win.alert("기준년월을 지정해주세요.");
        txb_YYYYMM.focus();
        return false;
    }
    if (basYymm.length < 6) {
        await $c.win.alert("올바른 날짜형식이 아닙니다.(YYYYMM)");
        txb_YYYYMM.focus();
        return false;
    }
    const month = Number(basYymm.substring(4, 6));
    if (Number(basYymm.substring(0, 1)) < 1 || month > 12 || month < 1) {
        await $c.win.alert("올바른 날짜형식이 아닙니다.");
        txb_YYYYMM.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.getForm
 * @author Inswave
 * @date 2026. 10. 28
 * @description 현재 탭의 입력 dataMap (1 → dma_form1, 2 → dma_form2, 4 → dma_form4, 5 → dma_form5, 그 밖은 null).
 * @returns {Object} dataMap 또는 null
 * @hidden N
 */
scwin.getForm = function () {
    return { 1 : dma_form1, 2 : dma_form2, 4 : dma_form4, 5 : dma_form5 }[scwin.curTp] ?? null;
};

/**
 * @method
 * @name scwin.clearForm
 * @author Inswave
 * @date 2026. 10. 28
 * @description 현재 탭 입력란 비우기. (원본 fn_Enable_Item·fn_Disable_Item 의 setObjectValue(…, "") — §6.4)
 * @returns
 * @hidden N
 */
scwin.clearForm = function () {
    const form = scwin.getForm();
    if (form) form.setEmptyValue();
};

/**
 * @method
 * @name scwin.setFormMode
 * @author Inswave
 * @date 2026. 10. 28
 * @description 현재 탭 입력란 잠금 상태. disabled 전부 잠금 / new 전부 입력 / update 키(종목·시작일자)만 잠금 — 심사서류첨부·기타안내의 update 는 new 와 같다.
 * 지수구분 콤보·일련번호는 원본도 잠그지 않는다(§8 #7). 배경색 토글(#b9d4f7/#ffffff)은 readOnly 기본 스타일로 대신한다.
 * (원본 fn_Enable_Item·fn_Disable_Item·fn_SetValue 의 ReadOnly/disabled — §6.4)
 * @param {String} mode disabled | new | update
 * @returns
 * @hidden N
 */
scwin.setFormMode = function (mode) {
    const tp = scwin.curTp;
    const lockAll = (mode === "disabled");
    const lockKey = (mode !== "new");    // update·disabled 는 종목·시작일자를 잠근다

    if (tp === 1) {
        img_COM_NM_1.setDisabled(lockKey);
        edt_SDate_1.setReadOnly(lockKey);
        [edt_EDate_1, txb_NotiTitle_1, txa_NotiContn_1].forEach(comp => comp.setReadOnly(lockAll));
    } else if (tp === 2) {
        img_COM_NM_2.setDisabled(lockKey);
        edt_SDate_2.setReadOnly(lockKey);
        txa_NotiContn_2.setReadOnly(lockAll);
    } else if (tp === 4) {
        [txb_NotiTitle_4, txa_NotiContn_4, edt_SDate_4_1, edt_SDate_4_2].forEach(comp => comp.setReadOnly(lockAll));
    } else if (tp === 5) {
        [txb_NotiTitle_5, txa_NotiContn_5, edt_SDate_5_1, edt_SDate_5_2].forEach(comp => comp.setReadOnly(lockAll));
    }
};

/**
 * @method
 * @name scwin.newForm
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 입력 준비 — 처리구분 I, 입력란 비우고 모두 입력 가능. (원본 btn_New_n onclick: TR_JOB = "I" + fn_Enable_Item — §6.4)
 * @returns
 * @hidden N
 */
scwin.newForm = function () {
    scwin.trJob = "I";
    scwin.clearForm();
    scwin.setFormMode("new");
};

/**
 * @method
 * @name scwin.setValue
 * @author Inswave
 * @date 2026. 10. 28
 * @description 목록 행을 입력란에 옮긴다(처리구분 U). 상장제한종목·지수구성종목변동은 키를 잠그고, 심사서류첨부·기타안내는 비운 뒤 모두 입력 가능하게 한다.
 * 목록의 YYYY-MM-DD 날짜는 '-' 를 지워 달력(yyyyMMdd)에 넣는다. (원본 fn_SetValue(row) — §6.5)
 * @param {Number} row 화면 행 번호 (0부터 — 원본은 1부터, row > 0 검사)
 * @returns
 * @hidden N
 */
scwin.setValue = function (row) {
    const tp = scwin.curTp;
    if (row < 0) return;

    scwin.trJob = "U";
    if (tp === 1) {
        const item = dlt_isulimit.getRowJSON(row);
        scwin.setFormMode("update");
        dma_form1.setJSON({
            isurCd : item.isurCd ?? "",
            comNm : item.comAbbrv ?? "",
            notiTitle : item.notiTitle ?? "",
            notiContn : item.notiContn ?? "",
            strtDd : scwin.toDd(item.strtDd),
            endDd : scwin.toDd(item.endDd)
        });
    } else if (tp === 2) {
        const item = dlt_uly.getRowJSON(row);
        scwin.setFormMode("update");
        dma_form2.setJSON({
            isurCd : item.isurCd ?? "",
            comNm : item.comAbbrv ?? "",
            notiTitle : item.notiTitle ?? "",
            notiContn : item.notiContn ?? "",
            strtDd : scwin.toDd(item.strtDd)
        });
    } else if (tp === 4 || tp === 5) {
        const item = dlt_declcontn.getRowJSON(row);
        const form = scwin.getForm();
        form.setEmptyValue();                 // 원본 fn_Enable_Item(비우고 입력 가능) 후 값 채움
        scwin.setFormMode("update");
        form.setJSON({
            notiTitle : item.notiTitle ?? "",
            notiContn : item.notiContn ?? "",
            strtDd : scwin.toDd(item.strtDd),
            endDd : scwin.toDd(item.endDd),
            infoRnd : item.infoRnd ?? ""
        });
    }
};

/**
 * @method
 * @name scwin.toDd
 * @author Inswave
 * @date 2026. 10. 28
 * @description 날짜 문자열의 '-' 제거 (YYYY-MM-DD → YYYYMMDD). (원본 replaceAll(…, "-", ""))
 * @param {String} value 날짜 문자열
 * @returns {String} YYYYMMDD
 * @hidden N
 */
scwin.toDd = function (value) {
    return String(value ?? "").replace(/-/g, "");
};

/**
 * @method
 * @name scwin.validateFields
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공통 검증(validateDataCollect) 호출 — 원본 검사 순서를 지키려고 항목 묶음마다 부른다(공통은 컨테이너 DOM 순서로 본다).
 * @param {Object} container 입력 표 그룹
 * @param {Object} fields 컴포넌트 id → 규칙
 * @returns {Promise<Boolean>} 통과하면 true
 * @hidden N
 */
scwin.validateFields = async function (container, fields) {
    const options = {
        validateType : "alert",
        checkType : "single",
        fields : fields
    };
    return await $c.validate.validateDataCollect(container, options);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 입력 검증(탭별). 필수·날짜 형식은 공통 검증, 시작·종료일 선후와 특수문자는 업무 검증. 심사서류첨부는 삭제(D)면 검사하지 않는다. (원본 fn_CheckForm — §6.6)
 * @param {String} trJob 처리구분 I·U·D
 * @returns {Promise<Boolean>} 통과하면 true
 * @hidden N
 */
scwin.validate = async function (trJob) {
    const tp = scwin.curTp;

    if (tp === 1) {
        if (!await scwin.validateFields(panel_6, { txb_ISUR_CD_1 : { required : true, name : "종목명" } })) return false;
        if (!await scwin.validateFields(panel_6, {
            edt_SDate_1 : { required : true, format : "date", name : "제한사유 발생시점" },
            edt_EDate_1 : { required : true, format : "date", name : "제한사유 종료시점" }
        })) return false;
        if (!await scwin.validateFields(panel_6, { txb_NotiTitle_1 : { required : true, name : "제한사유" } })) return false;
        if (dma_form1.get("strtDd") > dma_form1.get("endDd")) {
            await $c.win.alert("[제한사유 종료시점]을  이전으로 입력하세요.");    // 원본 문구 그대로 (§7.2)
            edt_SDate_1.focus();
            return false;
        }
    } else if (tp === 2) {
        if (!await scwin.validateFields(panel_7, { txb_ISUR_CD_2 : { required : true, name : "종목명" } })) return false;
        if (!await scwin.validateFields(panel_7, { edt_SDate_2 : { required : true, format : "date", name : "지수편출일" } })) return false;
        if (!await scwin.validateFields(panel_7, { cmb_NotiTitle_2 : { required : true, name : "지수구분" } })) return false;
    } else if (tp === 4) {
        if (trJob === "D") return true;    // 원본은 TR_JOB 이 "D" 가 아닐 때만 검사
        if (!await scwin.validateFields(panel_9, {
            txb_NotiTitle_4 : { required : true, name : "제목" },
            txa_NotiContn_4 : { required : true, name : "내용" }
        })) return false;
        if (scwin.chkXss(dma_form4.get("notiContn"))) {
            await $c.win.alert("허용되지 않는 문자가 들어가 있습니다.");
            txa_NotiContn_4.focus();
            return false;
        }
        return await scwin.validatePeriod(panel_9, dma_form4, edt_SDate_4_1, edt_SDate_4_2);
    } else if (tp === 5) {
        // 원본은 기타안내에 삭제 예외·특수문자 검사가 없다(§8 #8)
        if (!await scwin.validateFields(panel_8, {
            txb_NotiTitle_5 : { required : true, name : "제목" },
            txa_NotiContn_5 : { required : true, name : "내용" }
        })) return false;
        return await scwin.validatePeriod(panel_8, dma_form5, edt_SDate_5_1, edt_SDate_5_2);
    }
    return true;
};

/**
 * @method
 * @name scwin.validatePeriod
 * @author Inswave
 * @date 2026. 10. 28
 * @description 메시지 표시기간 검사 — 시작·종료일 필수·날짜 형식(공통) 후 시작일 ≤ 종료일. (원본 fn_CheckForm 탭4·5 — §6.6)
 * @param {Object} container 입력 표 그룹
 * @param {Object} form 입력 dataMap
 * @param {Object} calStart 시작일 달력
 * @param {Object} calEnd 종료일 달력
 * @returns {Promise<Boolean>} 통과하면 true
 * @hidden N
 */
scwin.validatePeriod = async function (container, form, calStart, calEnd) {
    const fields = {};
    fields[calStart.getID()] = { required : true, format : "date", name : "메시지 표시기간" };
    fields[calEnd.getID()] = { required : true, format : "date", name : "메시지 표시기간" };
    if (!await scwin.validateFields(container, fields)) return false;

    if (form.get("strtDd") > form.get("endDd")) {
        await $c.win.alert("[메시지 표시기간]의 시작일자는 종료일자보다 작아야 합니다.");
        calStart.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name scwin.chkXss
 * @author Inswave
 * @date 2026. 10. 28
 * @description 허용되지 않는 문자(\ & ! =) 포함 여부. 업무공통(cm/pcc/stf)에 없어 화면에 둔다. (원본 stf.js fn_chkXss — §6.7)
 * @param {String} str 검사할 문자열
 * @returns {Boolean} 포함하면 true
 * @hidden N
 */
scwin.chkXss = function (str) {
    // TODO: 화면 안내문은 「\, &, <, >」 인데 원본 함수는 \ & ! = 를 막는다 — 원본 함수 기준으로 두고 확인 (§8 #9, §10 #10)
    return /[\\&=!]/.test(String(str ?? ""));
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장(신규 I·수정 U). 검증 → 확인(MSG-A006) → 탭별 저장 → 성공 안내 후 재조회·입력란 잠금. (원본 fn_save + trs_Save OnSuccess — §6.8)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    const tp = scwin.curTp;
    if (!await scwin.validate(scwin.trJob)) return;
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const ok = (tp === 1 || tp === 2) ? await scwin.saveUlyChg(tp) : await scwin.saveDeclContn(tp);
    if (!ok) return;

    await scwin.afterTrs((scwin.trJob === "I") ? "저장" : "수정");
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제. 검증(심사서류첨부는 건너뜀) → 확인 → 탭별 삭제 → 성공 안내 후 재조회. 처리구분(scwin.trJob)은 바꾸지 않는다(§8 #3). (원본 fn_delete — §6.9)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    const tp = scwin.curTp;
    if (!await scwin.validate("D")) return;
    if (!await $c.lc.isProcess("D")) return;

    const ok = (tp === 1 || tp === 2) ? await scwin.removeUlyChg(tp) : await scwin.removeDeclContn(tp);
    if (!ok) return;

    await scwin.afterTrs("삭제");
};

/**
 * @method
 * @name scwin.afterTrs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장·수정·삭제 성공 후처리 — MSG-A001 안내 → 목록 재조회 → 입력란 비우고 잠금. (원본 trs_Save OnSuccess: fn_alertMsg('S'), fn_list_sync, fn_Disable_Item — §6.8, §8 #5)
 * @param {String} jobNm 처리명 (저장·수정·삭제)
 * @returns
 * @hidden N
 */
scwin.afterTrs = async function (jobNm) {
    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));
    await scwin.searchList();
    // 원본은 재조회 뒤 fn_Disable_Item 을 한 번 더 불러 첫 행 표시까지 지운다 — 그대로 둔다(§8 #5, §10 #8)
    scwin.trJob = "";
    scwin.clearForm();
    scwin.setFormMode("disabled");
};

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장·삭제 응답 판정. 통신 실패이거나 result 가 S 가 아니면 MSG-A002(+ 서버 메시지)를 안내하고 false. (원본 trs_Save OnFail — §5.8~5.11)
 * @param {Object} result executeDynamic 결과
 * @param {String} jobNm 처리명 (저장·수정·삭제)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.checkResult = async function (result, jobNm) {
    if (result.responseJSON?.success && dma_result.get("result") === "S") return true;

    const serverMsg = dma_result.get("resultMessage") ?? "";
    await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm) + (serverMsg ? "\n" + serverMsg : ""));
    return false;
};

/**
 * @method
 * @name scwin.makeInfo
 * @author Inswave
 * @date 2026. 10. 28
 * @description 지수구성종목변동 안내문작성 — 입력 검증 후 종목명·지수편출일·지수구분으로 안내문을 만들어 안내문 칸에 넣는다(저장은 하지 않음). (원본 fn_MakeInfo — §6.10)
 * @returns
 * @hidden N
 */
scwin.makeInfo = async function () {
    if (!await scwin.validate(scwin.trJob)) return;
    if (scwin.curTp !== 2) return;

    const strtDd = dma_form2.get("strtDd");
    const strtDdFmt = (strtDd.length === 8) ? strtDd.substring(0, 4) + "-" + strtDd.substring(4, 6) + "-" + strtDd.substring(6, 8) : strtDd;    // 원본 FormatDateEx
    const contents = dma_form2.get("comNm") + " 종목이 "
        + strtDdFmt + " 에 "
        + dma_form2.get("notiTitle") + " 에서 편출될 예정이므로 \n"
        + "해당 종목을 기초자산으로 하는 주식워런트증권은 상장이 불가합니다.\n"
        + "자세한 사항은 상품상장팀 담당자에게 문의하여 주시기 바랍니다.";
    dma_form2.set("notiContn", contents);
};

/**
 * @method
 * @name scwin.openCorpPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목(발행기관) 찾기 — 업무공통 $c.lc.popFindCorpChrg(ULDSTF92009)를 await 하고 고른 발행기관코드·명을 현재 탭 입력란에 넣는다. 취소·닫기면 그대로 둔다.
 * (원본 fn_GetParIsur·fn_SetParIsur + fn_PopFindCorpChrg — getPar/setPar → openPopup data + await, §6.11)
 * @returns
 * @hidden N
 */
scwin.openCorpPopup = async function () {
    const form = scwin.getForm();
    if (!form) return;

    // 원본 arrPar[2] fr_SecuGrpId 는 값을 넣는 곳이 없어 undefined 였다 → 빈 값. arrPar[0]·[1](현재 코드·명)·[3]("9" 전체데이터)은
    // 업무공통 함수가 받지 않는다 — TODO: 92009 전환본에 넘길 키 확인 (§10 #7)
    const result = await $c.lc.popFindCorpChrg("", "", "");

    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 필요한 필드로 판정한다(원본은 DBCLICKYN 이 "Y" 일 때만 반영).
    if (result?.isCloseButtonClick === true || $c.util.isEmpty(result?.isurCd)) return;

    form.set("isurCd", result.isurCd);
    form.set("comNm", result.comNm ?? "");
};

/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 엑셀 다운로드 — 파일명 {menuId}_{이름}_{yyyyMMddHHmmss}.xlsx (규칙 42). 원본 doLogSave(화면 사용 로그)는 옮기지 않는다. (원본 GridToExcel — §6.12)
 * @param {Object} grd 대상 gridView
 * @param {String} name 파일 이름 (원본 GridToExcel 첫 인자)
 * @returns
 * @hidden N
 */
scwin.excelDown = function (grd, name) {
    $c.data.downloadGridViewExcel(grd, {
        fileName : $c.win.getProgramId() + "_" + name + "_" + $c.date.getServerDateTime("yyyyMMddHHmmss") + ".xlsx"
    });
};
